    Set<V> set2 = new HashSet<>();
    int index = 0;
    List<V> vertices = new ArrayList<>(resultMap.values());
    for (V vertex : vertices) {
        if (index % 2 == 0) {
            set1.add(vertex);
        } else {
            set2.add(vertex);
        }
        index++;
    }

    // Add edges between all vertices in set1 and set2
