        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    Set<V> part1 = new HashSet<>();
    Set<V> part2 = new HashSet<>();

    // Assuming resultMap contains vertices for both parts of the bipartite graph
    for (String key : resultMap.keySet()) {
        if (key.startsWith("A_")) { // Assuming vertices for the first part are prefixed with "A_"
            part1.add(resultMap.get(key));
        } else if (key.startsWith("B_")) { // Assuming vertices for the second part are prefixed with "B_"
            part2.add(resultMap.get(key));
        }
    }

    // Add all vertices to the target graph
    target.addAllVertices(part1);
    target.addAllVertices(part2);

    // Connect every vertex in part1 to every vertex in part2
    for (V vertex1 : part1) {
        for (V vertex2 : part2) {
            target.addEdge(vertex1, vertex2);
        }
    }
}

