public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i >= str.length()) {
                throw new Exception("Invalid escape sequence");
            }
            c = str.charAt(i);
            switch (c) {
                case 'b':
                    output.append('\b');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'n':
                    output.append('\n');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '\"':
                    output.append('\"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= str.length()) {
                        throw new Exception("Invalid unicode escape sequence");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    output.append((char) Integer.parseInt(hex, 16));
                    i += 4;
                    break;
                default:
                    throw new Exception("Invalid escape sequence \\" + c);
            }
        } else {
            output.append(c);
        }
        i++;
    }
    return output.toString();
}

