    if (!path.endsWith("/")) {
        resultPath.append("/");
    }

    String[] relativeParts = relativePath.split("/");
    for (String part : relativeParts) {
        if (part.equals("..")) {
            int lastSlashIndex = resultPath.lastIndexOf("/");
            if (lastSlashIndex != -1) {
                resultPath.setLength(lastSlashIndex);
            }
        } else if (!part.equals(".")) {
            resultPath.append(part).append("/");
        }
    }

    // Remove the trailing slash if it's not the root
    if (resultPath.length() > 1 && resultPath.charAt(resultPath.length() - 1) == '/') {
        resultPath.setLength(resultPath.length() - 1);
