public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the paths by removing any trailing slashes
    path = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;
    relativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Process the relative path components
    int pathIndex = pathComponents.length - 1;
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (pathIndex > 0) {
                pathIndex--;
            }
        } else if (component.equals(".")) {
            // Stay at the same level, do nothing
        } else {
            // Add the component to the path
            pathComponents[++pathIndex] = component;
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= pathIndex; i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(pathComponents[i]);
    }

    return result.toString();
}

